svg.script:
let params = new URL(document.location.toString()).searchParams;
let scale_val = params.get('scale');
const scale = document.getElementById('scale');
const rect = document.getElementById('rect');
scale.setAttribute("transform","scale(" + scale_val + ")");
rect.setAttribute("height",100/scale_val + "%");
rect.setAttribute("width",100/scale_val +"%");
